/**
 * Polish. MU's proper nouns (class names, event names, Zen, MU Helper) stay
 * as they are - Polish servers use them untranslated. A line that names a
 * player or an item never carries a gendered past tense, because the name's
 * gender is unknowable.
 */

import type { LanguageLayer } from './layer';

export const polishLayer: LanguageLayer = {
  name: 'polish',
  code: 'pl',
  aliases: ['pl-PL'],
  label: 'Polski',
  region: 'PL',
  // Generated by `tools/localPacks.ts`: items, monsters, warps.
  dataPack: { folder: 'Pol', suffix: 'pol', encoding: 'windows-1250' },
};
